package cn.course.community;
import java.util.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:notificationworkbench;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"})
@AutoConfigureMockMvc @Transactional
class NotificationWorkbenchTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired Store s;@Autowired NotificationService notices;
 long uid(String who){return s.uid(who+"@example.test");}
 void clear(){s.db.update("DELETE FROM notification");}
 void send(String who,String kind,String audience){notices.send(uid(who),1,kind,audience,"local notification test","submission",1,"p-gap",uid("teacher"));}
 JsonNode getAs(String path,String who)throws Exception{return json.readTree(mvc.perform(get("/api"+path).with(user(who+"@example.test"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 @Test void summaryIsBoundedSafeMetadata()throws Exception{clear();send("student","FEEDBACK","MEMBER");var n=getAs("/notifications/summary","student");assertEquals(4,n.size());assertEquals(1,n.path("unreadCount").asInt());assertEquals(1,n.path("scopeUnreadCount").asInt());assertTrue(n.path("latestId").asLong()>0);assertFalse(n.toString().contains("p-gap"));}
 @Test void categoryFilterDoesNotChangeGlobalBadge()throws Exception{clear();send("student","FEEDBACK","MEMBER");send("student","EVALUATION","MEMBER");var n=getAs("/notifications?kind=FEEDBACK","student");assertEquals(1,n.path("items").size());assertEquals("FEEDBACK",n.path("items").get(0).path("kind").asText());assertEquals(2,n.path("unreadCount").asInt());assertEquals(1,n.path("scopeUnreadCount").asInt());}
 @Test void unmatchedCategoryHasExplicitZeroNotGlobalZero()throws Exception{clear();send("student","FEEDBACK","MEMBER");var n=getAs("/notifications?kind=MEMBERSHIP_CHANGE","student");assertTrue(n.path("items").isEmpty());assertEquals(1,n.path("unreadCount").asInt());assertEquals(0,n.path("scopeUnreadCount").asInt());assertEquals(0,n.path("latestId").asLong());}
 @Test void invalidFiltersAreRejectedOnAllEndpoints()throws Exception{for(String path:List.of("/notifications","/notifications/summary")){mvc.perform(get("/api"+path).param("kind","FEEDBACK' OR 1=1 --").with(user("student@example.test"))).andExpect(status().isBadRequest());}mvc.perform(put("/api/notifications/read-all?kind=unknown").with(user("student@example.test")).with(csrf())).andExpect(status().isBadRequest());}
 @Test void emptyCategoryRetainsCompatibility()throws Exception{clear();send("student","FEEDBACK","MEMBER");assertEquals(getAs("/notifications","student"),getAs("/notifications?kind=","student"));}
 @Test void scopedReadAllDoesNotMarkOtherKindsOrUsers()throws Exception{clear();send("student","FEEDBACK","MEMBER");send("student","EVALUATION","MEMBER");send("peer","FEEDBACK","MEMBER");mvc.perform(put("/api/notifications/read-all?kind=FEEDBACK").with(user("student@example.test")).with(csrf())).andExpect(jsonPath("updated").value(1));assertEquals(1,getAs("/notifications/summary","student").path("unreadCount").asInt());assertEquals(0,getAs("/notifications/summary?kind=FEEDBACK","student").path("scopeUnreadCount").asInt());assertEquals(1,getAs("/notifications/summary","peer").path("unreadCount").asInt());}
 @Test void repeatedScopedReadIsIdempotent()throws Exception{clear();send("student","FEEDBACK","MEMBER");for(int expected:List.of(1,0))mvc.perform(put("/api/notifications/read-all?kind=FEEDBACK").with(user("student@example.test")).with(csrf())).andExpect(jsonPath("updated").value(expected));}
 @Test void summaryRequiresSessionAndWritesRequireCsrf()throws Exception{mvc.perform(get("/api/notifications/summary")).andExpect(status().isUnauthorized());mvc.perform(put("/api/notifications/read-all?kind=FEEDBACK").with(user("student@example.test"))).andExpect(status().isForbidden());}
 @Test void filteredPagingStaysStableWhenNewerMessageArrives()throws Exception{clear();for(int i=0;i<25;i++)send("student","FEEDBACK","MEMBER");send("student","EVALUATION","MEMBER");var first=getAs("/notifications?kind=FEEDBACK","student");assertEquals(20,first.path("items").size());long before=first.path("nextCursor").asLong(),head=first.path("latestId").asLong();send("student","FEEDBACK","MEMBER");var second=getAs("/notifications?kind=FEEDBACK&before="+before,"student");assertEquals(5,second.path("items").size());for(var n:second.path("items"))assertTrue(n.path("id").asLong()<before);assertTrue(second.path("latestId").asLong()>head);assertEquals(26,second.path("scopeUnreadCount").asInt());assertFalse(second.path("hasMore").asBoolean());}
 @Test void summaryCountsDoNotFollowPagingOrUnreadFilter()throws Exception{clear();for(int i=0;i<22;i++)send("student","FEEDBACK","MEMBER");long id=s.id(s.one("SELECT id FROM notification ORDER BY id DESC LIMIT 1"),"id");notices.read(id,uid("student"));var first=getAs("/notifications?kind=FEEDBACK&unread=true","student");assertEquals(21,first.path("scopeUnreadCount").asInt());assertEquals(id,first.path("latestId").asLong());var last=getAs("/notifications?kind=FEEDBACK&unread=true&before="+first.path("nextCursor").asLong(),"student");assertEquals(1,last.path("items").size());assertEquals(21,last.path("scopeUnreadCount").asInt());assertEquals(id,last.path("latestId").asLong());}
 @Test void revokedMembershipHidesScopedRowsCountsAndReadWrites()throws Exception{clear();send("student","FEEDBACK","MEMBER");s.db.update("DELETE FROM course_member WHERE course_id=1 AND user_id=?",uid("student"));var n=getAs("/notifications?kind=FEEDBACK","student");assertTrue(n.path("items").isEmpty());assertEquals(0,n.path("unreadCount").asInt());assertEquals(0,n.path("latestId").asLong());mvc.perform(put("/api/notifications/read-all?kind=FEEDBACK").with(user("student@example.test")).with(csrf())).andExpect(jsonPath("updated").value(0));}
 @Test void teacherAudienceStaysHiddenAfterDemotion()throws Exception{clear();notices.send(uid("peer"),1,"SUBMISSION","TEACHER","staff only","submission",1,"",uid("teacher"));s.db.update("UPDATE course_member SET role='TEACHER' WHERE course_id=1 AND user_id=?",uid("peer"));assertEquals(1,getAs("/notifications/summary?kind=SUBMISSION","peer").path("scopeUnreadCount").asInt());s.db.update("UPDATE course_member SET role='STUDENT' WHERE course_id=1 AND user_id=?",uid("peer"));assertEquals(0,getAs("/notifications/summary?kind=SUBMISSION","peer").path("scopeUnreadCount").asInt());assertTrue(getAs("/notifications?kind=SUBMISSION","peer").path("items").isEmpty());}
 @Test void accessStampTracksOnlyOwnMembershipNotReadStateOrOtherUsers()throws Exception{clear();send("student","FEEDBACK","MEMBER");String before=getAs("/notifications/summary","student").path("accessStamp").asText();assertEquals(64,before.length());notices.readAll(uid("student"));s.db.update("UPDATE course_member SET role='ASSISTANT' WHERE course_id=1 AND user_id=?",uid("peer"));assertEquals(before,getAs("/notifications/summary","student").path("accessStamp").asText());s.db.update("UPDATE course_member SET role='ASSISTANT' WHERE course_id=1 AND user_id=?",uid("student"));assertNotEquals(before,getAs("/notifications/summary","student").path("accessStamp").asText());}
 @Test void removedMembershipChangesAccessStampAndSummaryContainsNoRows()throws Exception{String before=getAs("/notifications/summary","student").path("accessStamp").asText();s.db.update("DELETE FROM course_member WHERE course_id=1 AND user_id=?",uid("student"));var summary=getAs("/notifications/summary","student");assertNotEquals(before,summary.path("accessStamp").asText());assertEquals(0,summary.path("latestId").asLong());assertFalse(summary.has("items"));}
}
